using System.Text;
using PcTidy.Core;
using PcTidy.Core.Model;
using PcTidy.Features.Games.Clips;
using PcTidy.Features.Games.Common;
using PcTidy.Features.Games.Environment;
using PcTidy.Hosting;
using PcTidy.TestbedGen;

namespace PcTidy.Features.Games.Tests;

/// <summary>
/// One fake PC per test under testbed\games\, built with the real composition root in sandbox mode (real SafetyGuard,
/// Executor and Undo). Either generated by TestbedBuilder or hand-made for a specific layout. Deleted afterwards.
/// </summary>
internal sealed class GamesSandbox : IDisposable
{
    public static readonly string TestbedRoot = Path.Combine(FindCodeRoot(), "testbed", "games");
    public static readonly DateTime Now = new(2026, 11, 10, 12, 0, 0, DateTimeKind.Utc);

    private readonly bool _generated;

    /// <param name="area">Another testbed subfolder (e.g. "research-additions-3") instead of testbed\games.</param>
    public GamesSandbox(string name, SandboxProfile? profile = null, bool generate = false, Action<AppSettings>? configure = null, string? area = null)
    {
        Profile = profile ?? SandboxProfile.Default;
        var root = area is null ? TestbedRoot : Path.Combine(Path.GetDirectoryName(TestbedRoot)!, area);
        Root = Path.Combine(root, $"{name}-{Guid.NewGuid().ToString("N")[..6]}");
        _generated = generate;
        if (generate) TestbedBuilder.Generate(Root, TestbedSize.Small, Profile, new TestbedOptions { AnchorUtc = Now });
        else Directory.CreateDirectory(Root);
        Host = PcTidyHost.CreateSandbox(Root, Profile, configure);
        K = (SandboxKnownLocations)Host.Locations;
    }

    public string Root { get; }
    public SandboxProfile Profile { get; }
    public PcTidyHost Host { get; }
    public SandboxKnownLocations K { get; }

    public IGamesEnvironment Environment { get; set; } = new FakeEnvironment();
    public IMediaProbe Media { get; set; } = NullMediaProbe.Instance;

    public ScanContext Context(string? preset = null, IReadOnlySet<string>? running = null, ISafetyGuard? guard = null)
    {
        var c = Host.CreateScanContext(ScanDepth.Quick, preset: preset);
        return new ScanContext
        {
            Locations = c.Locations, Safety = guard ?? c.Safety, InUse = c.InUse, Settings = c.Settings, Walker = c.Walker, Depth = c.Depth,
            Preset = preset, System = c.System, RunningProcesses = running ?? new HashSet<string>(),
            Options = new Dictionary<string, object>
            {
                [GamesOptions.Now] = Now,
                [GamesOptions.Environment] = Environment,
                [GamesOptions.Media] = Media,
            },
        };
    }

    public string Put(string path, string text, DateTime? writtenUtc = null) => Put(path, Encoding.UTF8.GetBytes(text), writtenUtc);

    public string Put(string path, byte[] bytes, DateTime? writtenUtc = null)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.WriteAllBytes(path, bytes);
        if (writtenUtc is { } w)
        {
            File.SetCreationTimeUtc(path, w);
            File.SetLastWriteTimeUtc(path, w);
        }
        return path;
    }

    public static byte[] RandomBytes(int length, int seed)
    {
        var b = new byte[length];
        new Random(seed).NextBytes(b);
        return b;
    }

    // ---------------- Steam / Epic layouts ----------------

    public string SteamRoot => K.SteamRoot!;

    /// <summary>A Steam game: appmanifest + install folder with the given files (relative path → content).</summary>
    public string SteamGame(string library, string appId, string name, string dir, long? lastPlayed, long lastUpdated, params string[] files)
    {
        var apps = Path.Combine(library, "steamapps");
        var played = lastPlayed is { } p ? $"\t\"LastPlayed\"\t\t\"{p}\"\n" : "";
        Put(Path.Combine(apps, $"appmanifest_{appId}.acf"),
            $"\"AppState\"\n{{\n\t\"appid\"\t\t\"{appId}\"\n\t\"name\"\t\t\"{name}\"\n\t\"StateFlags\"\t\t\"4\"\n\t\"installdir\"\t\t\"{dir}\"\n" +
            $"\t\"LastUpdated\"\t\t\"{lastUpdated}\"\n{played}\t\"SizeOnDisk\"\t\t\"1048576\"\n}}\n");
        var install = Path.Combine(apps, "common", dir);
        foreach (var f in files) Put(Path.Combine(install, f), "x");
        Directory.CreateDirectory(install);
        return install;
    }

    public string LocalConfigPath(string account = "12345678") => Path.Combine(SteamRoot, "userdata", account, "config", "localconfig.vdf");

    public void Dispose()
    {
        Host.Dispose();
        try
        {
            if (_generated) TestbedBuilder.Delete(Root);
            else ForceDelete(Root);
        }
        catch { /* best effort: the testbed folder is disposable */ }
    }

    private static void ForceDelete(string dir)
    {
        if (!Directory.Exists(dir)) return;
        foreach (var f in Directory.EnumerateFiles(dir, "*", SearchOption.AllDirectories)) File.SetAttributes(f, FileAttributes.Normal);
        Directory.Delete(dir, recursive: true);
    }

    private static string FindCodeRoot()
    {
        var d = new DirectoryInfo(AppContext.BaseDirectory);
        while (d != null && !File.Exists(Path.Combine(d.FullName, "PcTidy.sln"))) d = d.Parent;
        return d?.FullName ?? throw new InvalidOperationException("PcTidy.sln not found");
    }
}

internal sealed class FakeEnvironment : IGamesEnvironment
{
    public List<RegistryGame> Registry { get; } = new();
    public List<StoreGame> Store { get; } = new();
    public byte[]? Nvidia { get; set; }
    public List<CompatibilitySetting> Compatibility { get; } = new();
    public IReadOnlyList<CompatibilitySetting> CompatibilitySettings() => Compatibility;
    public IReadOnlyList<RegistryGame> RegistryGames() => Registry;
    public IReadOnlyList<StoreGame> StoreGames() => Store;
    public byte[]? NvidiaCapturePathValue() => Nvidia;
}

/// <summary>Media facts by file name, and records every file it was asked about.</summary>
internal sealed class FakeMediaProbe : IMediaProbe
{
    public Dictionary<string, MediaInfo> Info { get; } = new(StringComparer.OrdinalIgnoreCase);
    public Dictionary<string, ulong> Hashes { get; } = new(StringComparer.OrdinalIgnoreCase);
    public List<string> Asked { get; } = new();

    public MediaInfo? Probe(string path)
    {
        Asked.Add(path);
        return Info.TryGetValue(Path.GetFileName(path), out var i) ? i : null;
    }

    public ulong? ThumbnailHash(string path, bool cacheOnly)
    {
        Asked.Add(path);
        return Hashes.TryGetValue(Path.GetFileName(path), out var h) ? h : null;
    }
}

/// <summary>
/// Test-only guard that allows everything, used ONLY to inspect exact planned text where today's real guard refuses the
/// target (Steam's localconfig.vdf sits in the protected Steam folder). Real-guard behaviour is tested separately.
/// </summary>
internal sealed class AllowAllGuard : ISafetyGuard
{
    public SafetyVerdict ClassifyPath(string path) => SafetyVerdict.Ok;
    public SafetyVerdict Check(PlanItem item) => SafetyVerdict.Ok;
    public bool IsInCloudRoot(string path) => false;
    public bool IsInsideProjectOrAppFolder(string path, out string? why) { why = null; return false; }
}
